(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8+Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.2)*8+Math.sin((x+y)*0.013-t*0.22)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 120+Math.cos(t*0.65+4)*55, 0.11, 2.1, 1.15],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*45, 0.13, 1.8, 0.88]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    for(let j=i+1;j<src.length;j++){
      const d = Math.sqrt((sx-src[i][0])**2+(sy-src[i][1])**2);
      const d2 = Math.sqrt((sx-src[j][0])**2+(sy-src[j][1])**2);
      cross += Math.sin((d*src[i][2]+d2*src[j][2])-t*(src[i][3]+src[j][3])*0.5)*0.15;
    }
    const d = Math.sqrt((sx-src[i][0])**2+(sy-src[i][1])**2);
    aS += Math.sin(d*src[i][2]-t*src[i][3])*src[i][4];
    iS += Math.sin(d*src[i][2]*0.7+t*src[i][3]*0.6+1.5)*src[i][4];
  }
  const n = src.length;
  const act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.025*Math.cos(t*0.1)+sy*0.03*Math.sin(t*0.12)+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*6-t*2.5)*0.15;
  const membrane = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.2-t*0.8)*Math.cos(sy*0.18+t*0.6)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.35+sy*0.28+t*3)*Math.cos(sx*0.22-sy*0.31-t*2.5)*0.12;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+cross)*2.2);
  const blend = reaction*0.65+membrane*0.2+micro*0.15;
  const v = blend*0.5+0.5;
  const vig = 1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/420*0.25;
  const pal = [[5,12,52],[12,45,88],[18,95,115],[28,148,138],[85,175,120],
    [185,185,65],[210,145,55],[195,85,60],[150,45,55],[70,22,60],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = (0.85+Math.sin(reaction*Math.PI)*0.15)*vig;
  const edge = Math.abs(reaction)>0.75?1.12:Math.abs(reaction)>0.5?1.04:1.0;
  const shimmer = 1.0+Math.sin(dist*0.08-t*3)*0.03;
  const L = lum*edge*shimmer;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*L)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*L)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*L)|0
  ];
}
